// Package brf implements the schema-neutral BRF v2 byte mechanics used by
// Go code generated by quarry-schema-compiler --language go.
//
// Generated code supplies all schema knowledge (record IDs, layout offsets,
// presence bits, bounds and enum values) and calls these primitives to write
// and validate records. The package has no schema interpreter, no reflection,
// no global state and no dependencies outside the Go standard library.
//
// Wire behavior matches the C, C++ and Python runtimes byte for byte: a
// 16-byte big-endian header, a presence bitmap and fixed region whose layout
// is computed by the compiler, and a contiguous variable region holding
// strings, bytes, arrays and variable-size nested records in schema
// declaration order. See docs/specifications/binary-record-format.md.
package brf

// GeneratedCodeAPIVersion is the compatibility epoch between generated Go code
// and this runtime. Generated packages fail to compile against a runtime with
// a different epoch. It is independent of the C, C++ and Python epochs and of
// the BRF wire format version.
const GeneratedCodeAPIVersion = 1

const (
	// FormatVersion is the BRF v2 brf_format_version header value.
	FormatVersion = 2
	// HeaderSize is the size of the BRF v2 record header in bytes.
	HeaderSize = 16
	// DescriptorSize is the size of a variable-field descriptor in bytes.
	DescriptorSize = 8
	// MaxVaruintBytes bounds an unsigned LEB128 value (64 bits).
	MaxVaruintBytes = 10
)

// Ptr returns a pointer to a copy of v. It is a convenience for setting
// optional scalar, enum and nested-record fields of generated structs.
func Ptr[T any](v T) *T { return &v }
